const b = $input.first().json.body || $input.first().json;

const cap = str => str ? str.charAt(0).toUpperCase() + str.slice(1) : '';

const months = ['January','February','March','April','May','June','July','August','September','October','November','December'];

let formatted_week_ending = b.week_ending || '';
try {
  if (b.week_ending) {
    const dt = new Date(b.week_ending + 'T00:00:00');
    if (!isNaN(dt.getTime())) {
      formatted_week_ending = dt.getDate() + ' ' + months[dt.getMonth()] + ' ' + dt.getFullYear();
    }
  }
} catch(e) {}

const now = new Date();

return [{
  json: {
    freelancer_name: cap(b.freelancer_name),
    freelancer_email: b.freelancer_email || '',
    client_name: cap(b.client_name),
    client_email: b.client_email || '',
    project_name: cap(b.project_name),
    work_done: b.work_done || '',
    next_steps: b.next_steps || '',
    blockers: b.blockers || 'None',
    completion: b.completion || '0',
    week_ending: b.week_ending || '',
    formatted_week_ending: formatted_week_ending,
    date_sent: now.getDate() + ' ' + months[now.getMonth()] + ' ' + now.getFullYear()
  }
}];

const d = $('Format Update Data').first().json;

const updateText = $input.first().json.update_text 
  || ($input.first().json.choices && $input.first().json.choices[0]?.message?.content)
  || '';

const months = ['January','February','March','April','May','June','July','August','September','October','November','December'];
let formattedWeekEnding = d.formatted_week_ending || '';
if (!formattedWeekEnding && d.week_ending) {
  try {
    const dt = new Date(d.week_ending + 'T00:00:00');
    if (!isNaN(dt.getTime())) {
      formattedWeekEnding = dt.getDate() + ' ' + months[dt.getMonth()] + ' ' + dt.getFullYear();
    }
  } catch(e) {}
}
if (!formattedWeekEnding) formattedWeekEnding = d.week_ending || '';

const openingParagraph = updateText || 'Made good progress this week on ' + (d.work_done || 'the project') + '.';

const html = '<!DOCTYPE html><html><head><meta charset="UTF-8"></head><body style="margin:0;padding:40px 20px;background:#ffffff;">'
  + '<div style="max-width:600px;margin:0 auto;">'
  + '<div style="padding:0 20px;">'
  + '<p style="font:700 11px/1 sans-serif;letter-spacing:4px;text-transform:uppercase;color:#999;margin:0 0 12px;">WEEKLY UPDATE</p>'
  + '<h1 style="font:700 32px/1.1 sans-serif;color:#111;margin:0 0 8px;">' + (d.project_name || '') + '</h1>'
  + '<p style="color:#999;font:14px/1 sans-serif;margin:0 0 32px;">Week ending ' + formattedWeekEnding + '</p>'
  + '<hr style="border:none;border-top:2px solid #111;margin:0 0 32px;">'
  + '<p style="margin:0 0 8px;color:#111;font:16px/1 sans-serif;">Hi ' + (d.client_name || '') + ',</p>'
  + '<p style="margin:0 0 32px;color:#444;font:16px/1.7 sans-serif;">' + openingParagraph + '</p>'
  + '<p style="margin:0 0 16px;color:#999;font:12px/1 sans-serif;letter-spacing:2px;text-transform:uppercase;">This week\'s progress</p>'
  + '<table style="width:100%;border-collapse:collapse;">'
  + '<tr style="border-top:1px solid #eee;"><td style="padding:14px 0;color:#999;font:13px/1 sans-serif;width:40%;">Project Progress</td><td style="padding:14px 0;color:#111;font:700 14px/1 sans-serif;">' + (d.completion || '0') + '% Complete</td></tr>'
  + '<tr style="border-top:1px solid #eee;"><td style="padding:14px 0;color:#999;font:13px/1 sans-serif;vertical-align:top;">This Week</td><td style="padding:14px 0;color:#111;font:14px/1.5 sans-serif;">' + (d.work_done || '') + '</td></tr>'
  + '<tr style="border-top:1px solid #eee;"><td style="padding:14px 0;color:#999;font:13px/1 sans-serif;vertical-align:top;">Next Week</td><td style="padding:14px 0;color:#111;font:14px/1.5 sans-serif;">' + (d.next_steps || '') + '</td></tr>'
  + '<tr style="border-top:1px solid #eee;border-bottom:1px solid #eee;"><td style="padding:14px 0;color:#999;font:13px/1 sans-serif;vertical-align:top;">Blockers</td><td style="padding:14px 0;color:#111;font:14px/1.5 sans-serif;">' + (d.blockers || 'None') + '</td></tr>'
  + '</table>'
  + '<p style="margin:32px 0;color:#444;font:16px/1.7 sans-serif;">If you have any questions or want to catch up, feel free to reach out anytime.</p>'
  + '<p style="font:14px/1 sans-serif;color:#444;margin:0 0 4px;">Best regards,</p>'
  + '<p style="font:700 16px/1 sans-serif;color:#111;margin:0;">' + (d.freelancer_name || '') + '</p>'
  + '</div>'
  + '</div></body></html>';

return [{
  json: {
    html: html,
    freelancer_name: d.freelancer_name || '',
    freelancer_email: d.freelancer_email || '',
    client_name: d.client_name || '',
    client_email: d.client_email || '',
    project_name: d.project_name || '',
    completion: d.completion || '0',
    week_ending: d.week_ending || '',
    formatted_week_ending: d.formatted_week_ending || formattedWeekEnding || '',
    date_sent: d.date_sent || '',
    work_done: d.work_done || '',
    next_steps: d.next_steps || '',
    blockers: d.blockers || 'None'
  }
}];
